export function validateNERVOUSLEFTSeed(): void {
  const slugs = new Set(
    NERVOUS_LEFT_STRUCTURES.map((structure) => structure.slug),
  );
  if (slugs.size !== NERVOUS_LEFT_STRUCTURES.length) {
    throw new Error(
      'Nervous system - left-sided structures seed contains duplicate structure slugs.',
    );
  }
  const meshNames = new Set(
    NERVOUS_LEFT_STRUCTURES.map((structure) => structure.meshName),
  );
  if (meshNames.size !== NERVOUS_LEFT_STRUCTURES.length) {
    throw new Error(
      'Nervous system - left-sided structures seed contains duplicate mesh names.',
    );
  }
  if (NERVOUS_LEFT_STRUCTURES.length !== 21) {
    throw new Error(
      'Nervous system - left-sided structures seed must contain exactly 21 structures.',
    );
  }
  for (const structure of NERVOUS_LEFT_STRUCTURES) {
    for (const relatedSlug of structure.relatedSlugs) {
      if (!slugs.has(relatedSlug)) {
        throw new Error(
          `Structure "${structure.slug}" references unknown related slug "${relatedSlug}".`,
        );
      }
    }
    if (structure.references.length === 0) {
      throw new Error(`Structure "${structure.slug}" has no references.`);
    }
    if (
      structure.meshName !== null &&
      !/^[a-z0-9_]+$/.test(structure.meshName)
    ) {
      throw new Error(
        `Structure "${structure.slug}" has an invalid mesh name "${structure.meshName}".`,
      );
    }
  }
}
